SELECT 
FROM MARKETING_LEAD_IMPORT_BATCH
WHERE record_status = 'ACTIVE'

    AND import_emp_id = #{importEmpId}


    AND (batch_no LIKE CONCAT('%', #{keyword}, '%')
         OR source_file_name LIKE CONCAT('%', #{keyword}, '%'))


    AND import_status = #{status}

ORDER BY import_time DESC, id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM MARKETING_LEAD_IMPORT_BATCH
WHERE record_status = 'ACTIVE'

    AND import_emp_id = #{importEmpId}


    AND (batch_no LIKE CONCAT('%', #{keyword}, '%')
         OR source_file_name LIKE CONCAT('%', #{keyword}, '%'))


    AND import_status = #{status}
